//! The key lives in `secrets/api.key`, which is listed in `.gitignore` and is
//! never committed. Keep it out of version control: use a secret manager or an
//! environment variable in CI and production.

use std::fmt;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

/// Default location of the API key, relative to the crate root.
pub const API_KEY_PATH: &str = "secrets/api.key";

#[derive(Debug)]
pub enum ApiKeyError {
    /// The key file could not be read.
    Io { path: PathBuf, source: io::Error },
    /// The key file was read but contains no key.
    Empty { path: PathBuf },
}

impl fmt::Display for ApiKeyError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ApiKeyError::Io { path, source } => {
                write!(f, "failed to read API key from {}: {source}", path.display())
            }
            ApiKeyError::Empty { path } => {
                write!(f, "API key file {} is empty", path.display())
            }
        }
    }
}

impl std::error::Error for ApiKeyError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            ApiKeyError::Io { source, .. } => Some(source),
            ApiKeyError::Empty { .. } => None,
        }
    }
}

/// Read the API key from `secrets/api.key` relative to the current directory.
pub fn read_api_key() -> Result<String, ApiKeyError> {
    read_api_key_from(Path::new(API_KEY_PATH))
}

/// Read the API key from an explicit path, trimming surrounding whitespace
/// (typically the trailing newline an editor appends).
pub fn read_api_key_from(path: impl AsRef<Path>) -> Result<String, ApiKeyError> {
    let path = path.as_ref();
    let raw = fs::read_to_string(path).map_err(|source| ApiKeyError::Io {
        path: path.to_path_buf(),
        source,
    })?;

    let key = raw.trim();
    if key.is_empty() {
        return Err(ApiKeyError::Empty {
            path: path.to_path_buf(),
        });
    }

    Ok(key.to_owned())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicU32, Ordering};

    static COUNTER: AtomicU32 = AtomicU32::new(0);

    /// Write `contents` to a fresh temp file and return its path.
    fn temp_key_file(contents: &str) -> PathBuf {
        let n = COUNTER.fetch_add(1, Ordering::Relaxed);
        let path = std::env::temp_dir().join(format!(
            "auth-test-{}-{n}.key",
            std::process::id()
        ));
        fs::write(&path, contents).expect("write temp key file");
        path
    }

    #[test]
    fn reads_key_and_trims_trailing_newline() {
        let path = temp_key_file("super-secret-key\n");
        assert_eq!(read_api_key_from(&path).unwrap(), "super-secret-key");
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn rejects_empty_file() {
        let path = temp_key_file("  \n");
        assert!(matches!(
            read_api_key_from(&path),
            Err(ApiKeyError::Empty { .. })
        ));
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn reports_missing_file() {
        let path = std::env::temp_dir().join("auth-test-definitely-missing.key");
        assert!(matches!(
            read_api_key_from(&path),
            Err(ApiKeyError::Io { .. })
        ));
    }
}
